  "OSOT 301": {
    "preq": [],
    "creq": [],
    "depn": [],
    "_id": "399bdc064af4c9ca3437714b",
    "name": "Introduction to Human Occupation",
    "cred": 3,
    "desc": "Explores human occupation, conceptualized as all activities people do based on need, obligation, or preference. As the core construct of the discipline of occupational science and practice of occupational therapy, human occupation is examined for its relation to personal and social determinants of health. [3-0-0]",
    "prer": "None"
  },
  "OSOT 511": {
    "preq": [],
    "creq": [],
    "depn": [],
    "_id": "46663095eb66a4d44f9c1c5d",
    "name": "Fundamentals of Occupational Therapy: Theory, Conceptual Models and the Practice Process",
    "cred": 3,
    "desc": "Fundamentals of occupational therapy, including values and beliefs, conceptual models, client-centred principles, and practice process frameworks are introduced. Professional reasoning is demonstrated through resolution of case-based client occupational issues. Critical appraisal of theory fosters nuanced understandings of occupation and health. [1-2-2].",
    "prer": "None"
  },
  "OSOT 513": {
    "preq": [],
    "creq": [],
    "depn": [],
    "_id": "ed259523002c6a4ad71e48f3",
    "name": "Health, Illness & Occupation",
    "cred": 3,
    "desc": "Concepts and models of occupation, health, and illness are introduced and appraised. Narratives from persons with lived experience and interactive assignments are used for acquiring biopsychosocial information on health conditions that impact occupational performance across lifespan and diverse life experiences. [1-0-1.5].",
    "prer": "None"
  },
  "OSOT 515": {
    "preq": [],
    "creq": [],
    "depn": [],
    "_id": "a2f81ec720ce91fe4df39e4b",
    "name": "Occupation in Practice I: Foundation of Occupational Therapy Assessment and Intervention",
    "cred": 3,
    "desc": "Labs, simulations and tutorials provide opportunities to practice evidenced based foundational skills, techniques and approaches in preparation for occupational therapy practice in the local and regional context. [0-3-3].",
    "prer": "None"
  },
  "OSOT 519": {
    "preq": [],
    "creq": [],
    "depn": [],
    "_id": "91a47b294d971fe29a6b7fc1",
    "name": "Professional Development of the Occupational Therapist I",
    "cred": 4,
    "desc": "Concepts of professionalism, reflexivity, cultural humility and collaboration are introduced to develop the skills of a self-directed, culturally safe, lifelong learner, who consciously uses theory, evidence and critical thinking skills to maintain, evaluate and improve their practice of occupational therapy.",
    "prer": "None"
  },
  "OSOT 525": {
    "preq": [],
    "creq": [],
    "depn": [],
    "_id": "a3ab5f48aef8dca23184103e",
    "name": "Occupation in Practice II: Advancing Theory, Assessment & Intervention",
    "cred": 5,
    "desc": "Building on OSOT 511 and OSOT 515, complex skills and approaches to enable client occupational engagement are applied through workshops and labs. Biomechanical, psychosocial, neuro-rehabilitative and developmental frames of reference will inform professional reasoning as students work through the occupational therapy practice process. [2-3-3].",
    "prer": "None"
  },
  "OSOT 527": {
    "preq": [],
    "creq": [],
    "depn": [],
    "_id": "4a7272963036cfe17d41c36a",
    "name": "Becoming an Evidence-Informed Occupational Therapy Practitioner",
    "cred": 3,
    "desc": "Assumptions and principles of qualitative and quantitative research designs; elements of basic research designs for investigating and evaluating occupational performance and diverse issues relevant to occupational science and occupational therapy are introduced, emphasizing critical appraisal of occupational therapy research literature. [2-0-2].",
    "prer": "None"
  },
  "OSOT 528": {
    "preq": [],
    "creq": [],
    "depn": [],
    "_id": "753d95533e037d951fd44e97",
    "name": "Occupational Therapy Practice: Fieldwork I",
    "cred": 3,
    "desc": "Preparation for practice concepts to facilitate integration of knowledge and skills introduced in term 1 of the MOT program. Demonstration of emerging Occupational Therapy competencies for a total of 5 weeks of supervised fieldwork experience in affiliated agencies is required.",
    "prer": "None"
  },
  "OSOT 538": {
    "preq": [],
    "creq": [],
    "depn": [],
    "_id": "7ad68e5b7687dff44b0752dc",
    "name": "Occupational Therapy Practice: Fieldwork II",
    "cred": 7,
    "desc": "Advanced integration of knowledge and skills introduced in terms 1, 2, 3 & 4 of the MOT program to demonstrate Occupational Therapy intermediate competencies for a total of 12 weeks of supervised fieldwork experience in affiliated health agencies.",
    "prer": "None"
  },
  "OSOT 545": {
    "preq": [],
    "creq": [],
    "depn": [],
    "_id": "e93d85f7dd5fd5ef9e83141a",
    "name": "Occupation in Practice III: Occupational Therapy Assessment and Intervention",
    "cred": 5,
    "desc": "A 3-term course, builds upon year 1 to further develop professional reasoning skills, synthesize theory and practice approaches in occupational therapy, and provide opportunities to acquire assessment and intervention skills according to the competencies required to enter occupational therapy practice. [0-2-2].",
    "prer": "None"
  },
  "OSOT 547": {
    "preq": [],
    "creq": [],
    "depn": [],
    "_id": "2b63fbfaa326240b1b85a6ae",
    "name": "Developing Evidence for Occupational Therapy Practice",
    "cred": 6,
    "desc": "Enhances knowledge of research (or program evaluation) process and provides hands-on experience to create, inform, and disseminate evidence relevant to occupational science or occupational therapy. [2-0-8].",
    "prer": "None"
  },
  "OSOT 549": {
    "preq": [],
    "creq": [],
    "depn": [],
    "_id": "cc7d1ae8f3c9624a19891a46",
    "name": "Professional Development of the Occupational Therapist II",
    "cred": 5,
    "desc": "Professional identity, professionalism, and cultural humility are further explored. Knowledge is applied to develop self-directed, culturally safe, lifelong learners. Conscious use of theory, evidence and critical thinking will be utilized to maintain, evaluate and improve occupational therapy practice.",
    "prer": "None"
  },
  "OSOT 551": {
    "preq": [],
    "creq": [],
    "depn": [],
    "_id": "b5ebf1109e258a22506a0935",
    "name": "Societal and Environmental Influences on Occupation and Occupational Therapy Practice",
    "cred": 3,
    "desc": "Current legislative, socio-political, economic, cultural, and service delivery issues influencing occupational therapy practice are addressed. The structural, systemic, and contextual influences upon clients' health and occupations are also examined. [2-0-2].",
    "prer": "None"
  },
  "OSOT 553": {
    "preq": [],
    "creq": [],
    "depn": [],
    "_id": "bef341c0a1e4ab6bcade1163",
    "name": "Innovations in Occupation: Developing and Evaluating Occupational Therapy Programs",
    "cred": 2,
    "desc": "To address inequities and meet the occupational needs of diverse communities, students will learn, critique and apply program development principles. Program development principles include needs assessment, program design, budgeting and resource planning, marketing, program evaluation, and proposal writing and presentation.",
    "prer": "None"
  },
